INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'el-modelado-de-las-emociones', 'El Modelado de las Emociones', 'Dinámica de sensibilidad kinestésica y expresión afectiva donde los scouts trabajan por parejas moldeando suavemente la postura del compañero para expresar estados de ánimo.', '<h2>📜 Descripción de El Modelado de las Emociones</h2>
<p><b>El Modelado de las Emociones</b> es una dinámica scout de educación afectiva, empatía y sensibilidad kinestésica. En esta actividad, los participantes se dividen en parejas compuestas por un <i>Escultor</i> y una <i>Estatua de Emociones</i>. El escultor recibe la consigna secreta de representar un estado de ánimo o una emoción (ej. alegría, serenidad, sorpresa, perseverancia o entusiasmo) y moldea delicadamente la posición de los brazos, hombros y rostro del compañero. El grupo observa en silencio y reflexiona sobre el significado del estado emocional representado antes de adivinar.</p>
<p>Esta dinámica fomenta la inteligencia emocional, el autocontrol y la confianza fraterna en Manada, Compañía y Tropa.</p>

<h2>🎲 ¿Cómo se juega El Modelado de las Emociones?</h2>
<p>Para llevar a cabo la dinámica con solemnidad y cuidado afectivo, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Organización en Parejas:</b> Se distribuyen los scouts por parejas y se determina el rol inicial de Escultor y Estatua.</li>
  <li><b>Consigna Emocional:</b> El dirigente muestra al Escultor una tarjeta que indica la emoción o actitud a representar.</li>
  <li><b>Moldeado Sensible:</b> El Escultor posiciona suavemente la cabeza, brazos y gestos del compañero (quien mantiene su cuerpo relajado y disponible) para dar forma a la escultura de la emoción.</li>
  <li><b>Observación y Silencio:</b> Una vez concluida la pose, la Estatua sostiene la figura inmóvil durante 20 segundos mientras las demás parejas observan en silencio de reflexión.</li>
  <li><b>Interpretar y Compartir:</b> Los observadores expresan lo que la figura les transmite antes de revelar la emoción asignada. Al terminar, se intercambian los roles.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de El Modelado de las Emociones</h2>
<p>La actividad valora la sensibilidad afectiva y el cuidado del compañero en el Tally:</p>
<ul>
  <li><b>Expresividad Emocional:</b> Otorgar 5 puntos a la patrulla o seisena que logre transmitir con mayor claridad la emoción asignada.</li>
  <li><b>Respeto y Delicadeza:</b> Otorgar 3 puntos a la pareja que demuestre el mayor cuidado kinestésico en el trato del compañero.</li>
  <li><b>Empatía de Observación:</b> Otorgar 3 puntos al grupo que realice las reflexiones más profundas sobre los estados de ánimo expuestos.</li>
</ul>', '/uploads/el-modelado-de-las-emociones.webp', 'publicado', '{"areas": ["afectividad", "carácter", "creatividad"], "unidades": ["manada", "compañía", "tropa"], "duracion": "20 minutos", "cantidad": "02 participantes", "lugares": ["Interior", "Exterior"], "materiales": ["Sin Materiales"], "objetivos": ["Fomentar la inteligencia y madurez emocional", "Estimular la empatía y la conducta asertiva", "Desarrollo de la expresión corporal", "Superar la inhibición personal"], "justificacion_areas": "El Modelado de las Emociones desarrolla la afectividad al brindar un canal seguro para explorar, nombrar y comprender estados de ánimo y vivencias emocionales. Fortalece el carácter al promover el compromiso de autosuperación y la responsabilidad sobre la propia madurez emocional. Estimula la creatividad a través de la interpretación kinestésica y la síntesis gestual.", "variaciones": "<b>Modelado de Transformación:</b> Iniciar la escultura con una postura que exprese tristeza o duda y moldearla gradualmente hasta transformarla en alegría y confianza.<br><b>El Escultor de la Ley:</b> Moldear posturas que representen vivencias de los artículos de la Ley Scout.<br><b>Moldeado de Estatuas en Espejo:</b> Dos escultores moldean simultáneamente dos estatuas para que interactúen en un diálogo de emociones sin palabras.", "recomendaciones": "Mantener una atmósfera serena y de absoluto respeto hacia el trabajo corporal y afectivo de los beneficiarios. Enfatizar la delicadeza física al manipular brazos y cuello. Permitir que los scouts compartan cómo se sintieron en el rol de estatua al finalizar la dinámica.", "objetivos_educativos": [{"id": "ab6e594f-b0a0-4e6d-96aa-7779299b02ef", "area": "Afectividad", "unidad": "Manada", "texto": "Trato con cariño a los demás en la Manada y me gusta que me traten igual.", "como_se_cumple": "Tratando con delicadeza y afecto el cuerpo de mi compañero al moldear su escultura."}, {"id": "c8993915-0234-464c-934e-2a09f8c4338e", "area": "Afectividad", "unidad": "Manada", "texto": "Digo lo que pienso sin ofender o insultar a mis compañeros ni burlarme de ellos.", "como_se_cumple": "Expresando emociones e interpretando las esculturas del grupo con respeto y calidez."}, {"id": "2f8359db-221e-4a64-b2df-2b3e7b74a2db", "area": "Afectividad", "unidad": "Compañía", "texto": "Escucho las opiniones de las demás personas y si no estoy de acuerdo lo digo con respeto.", "como_se_cumple": "Escuchando con atención las vivencias emocionales compartidas por las integrantes de la patrulla."}, {"id": "672a5da0-8cab-42bb-85dd-0d1f285a1b91", "area": "Afectividad", "unidad": "Compañía", "texto": "Digo lo que pienso con respeto hacia las demás personas.", "como_se_cumple": "Comunicando sentimientos con asertividad y manteniendo un clima de madurez emocional."}, {"id": "a4060c60-7ce9-425b-bf2a-76941a689937", "area": "Afectividad", "unidad": "Tropa", "texto": "Escucho las opiniones de los demás personas y si no estoy de acuerdo lo digo con respeto.", "como_se_cumple": "Valorando la sensibilidad afectiva y los distintos estados de ánimo observados en el grupo."}, {"id": "4ade9c82-6b0d-4a44-8bc6-2eb47a011ffb", "area": "Afectividad", "unidad": "Tropa", "texto": "Digo lo que pienso con respeto hacia los demás personas.", "como_se_cumple": "Expresando estados de ánimo con madurez y contención afectiva hacia los pares."}, {"id": "eba5dac5-e1aa-498d-8d94-9655162890e5", "area": "Carácter", "unidad": "Manada", "texto": "Entiendo que es bueno que tenga metas que me ayuden a ser cada día mejor.", "como_se_cumple": "Comprendiendo la importancia de manejar mis emociones para crecer cada día como persona."}, {"id": "feeaf72d-4c33-4edd-8513-000a659d0491", "area": "Carácter", "unidad": "Manada", "texto": "Me propongo tareas y metas que me ayudan a superar mis defectos.", "como_se_cumple": "Trabajando en mi autocontrol y superando la timidez al expresar mis sentimientos."}, {"id": "2385386e-34db-4282-9934-7fcc515cb449", "area": "Carácter", "unidad": "Compañía", "texto": "Me propongo metas para ser mejor.", "como_se_cumple": "Asumiendo la responsabilidad personal sobre mi desarrollo afectivo e interpersonal."}, {"id": "672c638b-637e-4518-9dfb-ec92fb03c5cf", "area": "Carácter", "unidad": "Compañía", "texto": "Soy constante en mis propósitos.", "como_se_cumple": "Perseverando en la búsqueda de equilibrio y buen trato dentro de la patrulla."}, {"id": "41386aca-6175-4483-9e3b-54ac85ca5eb9", "area": "Carácter", "unidad": "Tropa", "texto": "Me propongo metas para ser mejor.", "como_se_cumple": "Estableciendo propósitos de autosuperación personal en el manejo de mis reacciones."}, {"id": "71413ac6-8ae9-4034-b580-e2f1c2f9f42c", "area": "Carácter", "unidad": "Tropa", "texto": "Me esfuerzo cada vez más en superar mis defectos.", "como_se_cumple": "Esforzándome conscientemente por dominar impulsos y cultivar la serenidad."}, {"id": "ec280dd0-2d80-4b84-86ad-2d362da14886", "area": "Creatividad", "unidad": "Manada", "texto": "Me gusta participar en juegos de observación.", "como_se_cumple": "Observando los rasgos faciales y posturales para descifrar la emoción representada."}, {"id": "dcdcce42-6b31-45f7-a135-290f0f74b5a6", "area": "Creatividad", "unidad": "Manada", "texto": "Me gustan los juegos en que tengo que usar mi agilidad mental.", "como_se_cumple": "Asociando con rapidez gestos simbólicos con conceptos afectivos complejos."}, {"id": "e1b7276f-4fd2-4c39-a32a-bd7fadbee702", "area": "Creatividad", "unidad": "Compañía", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Expresando con lenguaje plástico y verbal las percepciones de la dinamica."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "unidad": "Compañía", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Analizando la expresión corporal desde la perspectiva del espectador."}, {"id": "49ae6ac6-be8f-4f2c-8b3e-6711d041181f", "area": "Creatividad", "unidad": "Tropa", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Aportando agilidad de interpretación gestual en los ejercicios de la Tropa."}, {"id": "3d0dff9b-11cd-4a30-b3a6-ec011ad95062", "area": "Creatividad", "unidad": "Tropa", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Sintetizando emociones sutiles mediante la anatomía kinésica de la estatua."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

